import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.C9sp7nFj.js";const S=JSON.parse('{"title":"MovLW 摆动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovLW.md","filePath":"3. 指令/1. 运动指令/MovLW.md","lastUpdated":1778862643000}'),a={name:"3. 指令/1. 运动指令/MovLW.md"};function c(n,t,s,O,l,i){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="movlw-摆动" tabindex="-1">MovLW 摆动 <a class="header-anchor" href="#movlw-摆动" aria-label="Permalink to &quot;MovLW 摆动&quot;">​</a></h1><p>摆动指令（MovLW）是指机器人根据设定的摆动频率、摆动幅度，在直线前进的过程中同时进行摆弧运动。该指令常用于焊接应用中的编织焊（Weave Welding），以实现更宽的焊缝覆盖。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovLW(P, [V], [B], [C], [Tool], [Coord], [PayLoad], WEAVE, [O], [DO])</p><p>MovLW(目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], 摆动参数, [姿态控制], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的直线运动终点位置。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人直线前进的速度。SPEED 变量中的 <code>tcp</code>（平移）和 <code>ori</code>（旋转）分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式（无过渡、相对、绝对、缺省）。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡半径/数值。</td><td>可选，默认 C100</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量 / 变位机变量</td><td>机器人执行轨迹时使用的用户坐标系或变位机坐标系。</td><td>可选，默认使用当前系统中设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>WEAVE</td><td>WEAVE 变量</td><td>定义摆动动作的核心参数，包括：<strong>摆动频率</strong>（每秒摆动的次数）、<strong>摆动幅度</strong>（摆动中心线两侧的宽度）、<strong>停止时间</strong>（在摆动极点处的停留时间）、<strong>旋转参数</strong>（摆动过程中的姿态变化）。</td><td>必填</td></tr><tr><td>[O]</td><td>enum（GOVRON / GOVROFF）</td><td><code>GOVRON</code>：受全局速度倍率影响（默认）。<br><code>GOVROFF</code>：不受全局速度倍率影响，严格按设定速度运行。</td><td>可选，默认 GOVRON</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后触发的 IO 操作（如 <code>SetDO</code>、<code>PulseOut</code> 等）。目前支持：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table>',9)])])}const m=d(a,[["render",c]]);export{S as __pageData,m as default};
